L275:     // handler, then hand the Executor to the client.
L276:     fn build_client() -> Result<APCore, ModuleError> {
L277:         let mut executor = Executor::new(Arc::new(Registry::new()), Arc::new(Config::default()));
L278:         executor.set_approval_handler(Box::new(CallbackApprovalHandler::new(|request| async move {
L279:             if request.arguments["amount_cents"].as_i64().unwrap_or(0) <= 10_000 {
L280:                 Ok(ApprovalResult::approved("policy:small-refund"))
L281:             } else {
L282:                 Ok(ApprovalResult::rejected("refunds over 100.00 need a reviewer"))
L283:             }
L284:         })));
L285:         let client = APCore::with_options(None, Some(executor), None, None);
L286:         client.register("finance.refund", Box::new(RefundModule))?;
