L291:     async fn main() -> Result<(), ModuleError> {
L292:         let client = build_client()?;
L293:         let args = json!({"order_id": "o-1", "amount_cents": 2_500, "reason": "duplicate"});
L294:         let result = client.call("finance.refund", args, None, None).await?;
