L313:     class ReviewQueueHandler:
L314:         """Queues each request and answers once a reviewer has decided."""
L315: 
L316:         def __init__(self) -> None:
L317:             self._decisions: dict[str, ApprovalResult | None] = {}
L318: 
L319:         async def request_approval(self, request: ApprovalRequest) -> ApprovalResult:
L320:             approval_id = uuid.uuid4().hex
L321:             self._decisions[approval_id] = None  # open a review ticket here
L322:             return ApprovalResult(status="pending", approval_id=approval_id, reason="queued for review")
L323: 
L324:         async def check_approval(self, approval_id: str) -> ApprovalResult:
L325:             if approval_id not in self._decisions:
L326:                 return ApprovalResult(status="rejected", reason="unknown or already used approval id")
L327:             decision = self._decisions[approval_id]
L328:             if decision is None:
L329:                 return ApprovalResult(status="pending", approval_id=approval_id, reason="still in review")
L330:             del self._decisions[approval_id]  # a token is good for one call
L331:             return decision
L332: 
