L403:     `use apcore::{ApprovalHandler, ApprovalRequest, ErrorCode};
L404:     use std::collections::HashMap;
L405:     use std::sync::atomic::{AtomicU64, Ordering};
L406:     use std::sync::Mutex;
L407: 
L408:     /// Queues each request and answers once a reviewer has decided.
L409:     #[derive(Debug, Default)]
L410:     struct ReviewQueueHandler {
L411:         next_id: AtomicU64,
L412:         decisions: Mutex<HashMap<String, Option<ApprovalResult>>>,
L413:     }
L414: 
L415:     impl ReviewQueueHandler {
L416:         fn record(&self, approval_id: &str, approved: bool, reviewer: &str) {
L417:             let decision = if approved {
L418:                 ApprovalResult::approved(reviewer)
L419:             } else {
L420:                 ApprovalResult::rejected(format!("rejected by {reviewer}"))
L421:             };
L422:             self.decisions.lock().unwrap().insert(approval_id.to_string(), Some(decision));
L423:         }
L424:     }
L425: 
L426:     fn pending(approval_id: &str, reason: &str) -> ApprovalResult {
L427:         let mut result = ApprovalResult::default(); // #[non_exhaustive]: assign fields
L428:         result.status = "pending".to_string();
L429:         result.approval_id = Some(approval_id.to_string());
L430:         result.reason = Some(reason.to_string());
L431:         result
L432:     }
