L434:     #[async_trait]
L435:     impl ApprovalHandler for ReviewQueueHandler {
L436:         async fn request_approval(&self, _request: &ApprovalRequest) -> Result<ApprovalResult, ModuleError> {
L437:             let approval_id = format!("apr-{}", self.next_id.fetch_add(1, Ordering::SeqCst));
L438:             self.decisions.lock().unwrap().insert(approval_id.clone(), None); // open a review ticket here
L439:             Ok(pending(&approval_id, "queued for review"))
L440:         }
L441:         async fn check_approval(&self, approval_id: &str) -> Result<ApprovalResult, ModuleError> {
L442:             let mut decisions = self.decisions.lock().unwrap();
L443:             Ok(match decisions.get(approval_id) {
L444:                 None => ApprovalResult::rejected("unknown or already used approval id"),
L445:                 Some(None) => pending(approval_id, "still in review"),
L446:                 // A token is good for one call.
L447:                 Some(Some(_)) => decisions.remove(approval_id).flatten().expect("decision present"),
L448:             })
L449:         }
L450:     }
